
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_sfat_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_sfat", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.103934414598355e+00, -4.022003539245063e+00, -3.907265388888305e+00, -3.748461840247797e+00, -3.532351799140241e+00, -3.245286657619227e+00, -2.876885127244162e+00, -2.426487389621154e+00, -1.911240132437193e+00, -1.369081371132669e+00, -8.516417917428558e-01, -5.259461739251401e-01, -4.339169019008349e-01, -3.328910651447088e-01, -2.034770964858726e-01, -8.682186532481953e-02, -1.792276187518596e-02, -9.025330687300208e-04, -8.903022323316777e-06, -1.242322631106221e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


